create schema if not exists ged;
create extension if not exists pgcrypto;
create table if not exists ged.contract_service_catalog(id uuid primary key default gen_random_uuid(),tenant_id uuid null,service_code varchar(80) not null,description text not null,nature varchar(40) not null default 'UST',unit_name varchar(80) not null default 'UST',unit_value numeric(14,2) not null default 0 check(unit_value>=0),default_active boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz null,reg_status char(1) not null default 'A');
create table if not exists ged.contract_productivity_entry(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,service_id uuid not null references ged.contract_service_catalog(id),source_type varchar(80),source_id uuid,document_id uuid,box_id uuid,quantity numeric(14,2) not null default 0 check(quantity>0),unit_value numeric(14,2) not null default 0 check(unit_value>=0),total_value numeric(14,2) not null default 0,performed_by uuid,performed_by_name text,performed_at timestamptz not null default now(),notes text,evidence_required boolean not null default false,status varchar(40) not null default 'DRAFT',created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.contract_measurement_period(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,period_code varchar(40) not null,reference_month integer not null check(reference_month between 1 and 12),reference_year integer not null,status varchar(40) not null default 'OPEN',opened_by uuid,opened_at timestamptz not null default now(),closed_by uuid,closed_at timestamptz,submitted_by uuid,submitted_at timestamptz,approved_by uuid,approved_at timestamptz,rejected_by uuid,rejected_at timestamptz,rejection_reason text,gross_amount numeric(14,2) not null default 0,glosa_amount numeric(14,2) not null default 0,net_amount numeric(14,2) not null default 0,notes text,reg_status char(1) not null default 'A');
create table if not exists ged.contract_measurement_item(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,period_id uuid not null references ged.contract_measurement_period(id),service_id uuid not null references ged.contract_service_catalog(id),description text not null,nature varchar(40) not null default 'UST',unit_value numeric(14,2) not null default 0,quantity numeric(14,2) not null default 0,gross_amount numeric(14,2) not null default 0,glosa_amount numeric(14,2) not null default 0,net_amount numeric(14,2) not null default 0,status varchar(40) not null default 'PENDING',notes text,reg_status char(1) not null default 'A');
create table if not exists ged.contract_measurement_evidence(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,period_id uuid references ged.contract_measurement_period(id),item_id uuid references ged.contract_measurement_item(id),source_type varchar(80),source_id uuid,title text not null,description text,evidence_hash text,payload_json jsonb,registered_by uuid,registered_by_name text,registered_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.contract_glosa(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,period_id uuid not null references ged.contract_measurement_period(id),item_id uuid references ged.contract_measurement_item(id),glosa_number varchar(60) not null,reason text not null,amount numeric(14,2) not null default 0 check(amount>=0),status varchar(40) not null default 'OPEN',opened_by uuid,opened_at timestamptz not null default now(),resolved_by uuid,resolved_at timestamptz,resolution_notes text,reg_status char(1) not null default 'A');
create table if not exists ged.contract_acceptance_event(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,period_id uuid not null references ged.contract_measurement_period(id),event_type varchar(80) not null,title text not null,description text,performed_by uuid,performed_by_name text,occurred_at timestamptz not null default now(),payload_json jsonb,reg_status char(1) not null default 'A');
create unique index if not exists ux_contract_service_catalog_code on ged.contract_service_catalog(coalesce(tenant_id,'00000000-0000-0000-0000-000000000000'::uuid),service_code) where reg_status='A';
create index if not exists ix_contract_productivity_entry_tenant_date on ged.contract_productivity_entry(tenant_id,performed_at desc,status) where reg_status='A';
create unique index if not exists ux_contract_measurement_period on ged.contract_measurement_period(tenant_id,reference_year,reference_month) where reg_status='A';
create index if not exists ix_contract_measurement_item_period on ged.contract_measurement_item(period_id,status) where reg_status='A';
create index if not exists ix_contract_glosa_period on ged.contract_glosa(period_id,status) where reg_status='A';
create index if not exists ix_contract_evidence_period on ged.contract_measurement_evidence(period_id,registered_at desc) where reg_status='A';
